import{_ as e,r as s,o,c as l,e as a,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"渲染视图 - October CMS - 3.x","titleTemplate":false,"description":"了解页面内容的存储和渲染方式。","frontmatter":{"subtitle":"了解页面内容的存储和渲染方式。"},"headers":[{"level":2,"title":"局部视图","slug":"局部视图","link":"#局部视图","children":[{"level":3,"title":"提示局部视图","slug":"提示局部视图","link":"#提示局部视图","children":[]},{"level":3,"title":"检查提示是否已隐藏","slug":"检查提示是否已隐藏","link":"#检查提示是否已隐藏","children":[]}]},{"level":2,"title":"布局和子布局","slug":"布局和子布局","link":"#布局和子布局","children":[{"level":3,"title":"带侧边栏的表单","slug":"带侧边栏的表单","link":"#带侧边栏的表单","children":[]}]},{"level":2,"title":"扩展布局","slug":"扩展布局","link":"#扩展布局","children":[]}],"relativePath":"3.x/zh-cn/extend/system/views.md","filePath":"3.x/zh-cn/extend/system/views.md"}'),r={name:"3.x/zh-cn/extend/system/views.md"};function u(k,n,d,g,h,m){const t=s("pre-heading"),p=s("post-heading");return o(),l("div",null,[a(t),n[0]||(n[0]=c("h1",null,"渲染视图",-1)),a(p),n[1]||(n[1]=i(`<p>视图位于与控制器同名的目录中。</p><pre class="dir-container"><code><p>├── plugins
|   └── acme
|       └── blog
|           ├── controllers
|           |   ├── users  <em>← 视图目录</em>
|           |   |   ├── <code>_partial.php</code>  <em>← 局部视图文件</em>
|           |   |   └── <code>index.php</code>  <em>← 视图文件</em>
|           |   └── Users.php  <em>← 控制器类</em>
|           └── Plugin.php</p>
</code></pre><h2 id="局部视图"><a href="#局部视图" class="header-anchor">#</a> 局部视图</h2><p>后端局部视图是扩展名为 <strong>php</strong> 的文件，位于<a href="./controllers.html">控制器视图</a>目录中。局部视图文件名应以下划线开头：<strong>_partial.php</strong>。局部视图可以从后端页面或另一个局部视图中渲染。使用控制器的 <code>makePartial</code> 方法渲染局部视图。该方法接受两个参数——局部视图名称和可选的要传递给局部视图的变量数组。示例：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">makePartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;sidebar&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;showHeader&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h3 id="提示局部视图"><a href="#提示局部视图" class="header-anchor">#</a> 提示局部视图</h3><p>你可以在后端渲染信息面板，称为提示，用户可以隐藏它们。第一个参数应该是一个唯一的键，用于记住提示是否已被隐藏。第二个参数是对局部视图的引用。第三个参数可以是传递给局部视图的一些额外视图变量，以及一些提示属性。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">makeHintPartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;my_hint_key&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;my_hint_partial&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;foo&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;bar&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><p>你也可以通过将键值设置为 null 来禁用隐藏提示的功能。此提示将始终显示：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">makeHintPartial</span><span class="token punctuation">(</span><span class="token constant">null</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;my_hint_partial&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><p>以下属性可用：</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>type</strong></td><td>设置提示的颜色，支持的类型：danger、info、success、warning。默认值：info。</td></tr><tr><td><strong>title</strong></td><td>向提示添加标题部分。</td></tr><tr><td><strong>subtitle</strong></td><td>除标题外，向标题部分添加第二行。</td></tr><tr><td><strong>icon</strong></td><td>除标题外，向标题部分添加图标。</td></tr></tbody></table></div><h3 id="检查提示是否已隐藏"><a href="#检查提示是否已隐藏" class="header-anchor">#</a> 检查提示是否已隐藏</h3><p>如果你使用提示，你可能会发现检查用户是否已隐藏它们很有用。使用 <code>isBackendHintHidden</code> 方法可以轻松实现。它接受一个参数，即你在最初调用 <code>makeHintPartial</code> 时指定的唯一键。如果提示已被隐藏，该方法返回 true，否则返回 false：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">isBackendHintHidden</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;my_hint_key&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">:</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token comment">&lt;!-- Do something when the hint is hidden --&gt;</span>
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">endif</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h2 id="布局和子布局"><a href="#布局和子布局" class="header-anchor">#</a> 布局和子布局</h2><p>后端布局位于插件的可选 <strong>layouts/</strong> 目录中。自定义布局通过控制器对象的 <code>$layout</code> 属性设置。它默认使用名为 <code>default</code> 的系统布局。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">/**
 * @var string layout to use for the view.
 */</span>
<span class="token keyword">public</span> <span class="token variable">$layout</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;mycustomlayout&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>布局还提供了向 BODY 标签附加自定义 CSS 类的选项。这可以通过控制器的 <code>$bodyClass</code> 属性设置。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">/**
 * @var string bodyClass (CSS) to add to the layout.
 */</span>
<span class="token keyword">public</span> <span class="token variable">$bodyClass</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;compact-container&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>以下 body 类适用于默认布局：</p><ul><li><strong>compact-container</strong> - 所有边不使用内边距。</li><li><strong>slim-container</strong> - 左右不使用内边距。</li><li><strong>breadcrumb-flush</strong> - 使页面面包屑与下方元素齐平。</li></ul><h3 id="带侧边栏的表单"><a href="#带侧边栏的表单" class="header-anchor">#</a> 带侧边栏的表单</h3><p>布局也可以像局部视图一样使用，更像是一个全局局部视图。系统提供了一个名为 <code>form-with-sidebar</code> 的示例，展示了一种实现子布局结构的新颖方式。</p><p>在使用此布局样式之前，请确保你的控制器通过在操作方法或构造函数中设置 body 类 <code>compact-container</code> 来使用它。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">bodyClass</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;compact-container&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>此布局使用两个占位符，一个名为 <strong>form-contents</strong> 的主要内容区域和一个名为 <strong>form-sidebar</strong> 的辅助侧边栏。以下是示例：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">&lt;!-- Primary content --&gt;</span>
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token class-name static-context">Block</span><span class="token operator">::</span><span class="token function">put</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;form-contents&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
    Main content
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token class-name static-context">Block</span><span class="token operator">::</span><span class="token function">endPut</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>

<span class="token comment">&lt;!-- Complimentary sidebar --&gt;</span>
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token class-name static-context">Block</span><span class="token operator">::</span><span class="token function">put</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;form-sidebar&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
    Side content
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token class-name static-context">Block</span><span class="token operator">::</span><span class="token function">endPut</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>

<span class="token comment">&lt;!-- Layout execution --&gt;</span>
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token class-name static-context">Block</span><span class="token operator">::</span><span class="token function">put</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;body&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">open</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;class&#39;</span><span class="token operator">=&gt;</span><span class="token string single-quoted-string">&#39;layout stretch&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
        <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">makeLayout</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;form-with-sidebar&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">close</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token class-name static-context">Block</span><span class="token operator">::</span><span class="token function">endPut</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><p>布局在最后一个部分通过覆盖每个后端布局使用的 <strong>body</strong> 占位符来执行。它将所有内容包裹在 <code>&lt;form /&gt;</code> HTML 标签中，并渲染名为 <strong>form-with-sidebar</strong> 的子布局。此文件位于 <strong>modules/backend/layouts/form-with-sidebar.php</strong>。</p><h2 id="扩展布局"><a href="#扩展布局" class="header-anchor">#</a> 扩展布局</h2><p><code>fireViewEvent</code> 用于多个区域来<a href="./../extending.html">扩展后端区域</a>。<code>backend.layout.extendHead</code> 事件可用于扩展布局的 head 元素。返回值应包含要包含的标记。以下示例向每个后端页面添加一个 JavaScript 文件。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;backend.layout.extendHead&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$controller</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;&lt;script src=&quot;/app/assets/js/myscript.js&quot;&gt;&lt;/script&gt;&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>控制器作为第一个参数可用于事件，这可以用于定位特定的控制器。以下示例仅向 Tailor 条目控制器添加特定的 CSS 样式。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;backend.layout.extendHead&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$controller</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$controller</span> <span class="token keyword">instanceof</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>Tailor<span class="token punctuation">\\</span>Controllers<span class="token punctuation">\\</span>Entries</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;&lt;styles&gt; /* ... */ &lt;/styles&gt;&#39;</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div>`,34))])}const y=e(r,[["render",u]]);export{v as __pageData,y as default};
